{"content":"1|//! The threetched service paths shared by tched-router plugin surfaces.
2|//! Defaults mirror deploy/runit/tched-router/run; service overrides use its
3|//! THREETCHED_BIN, THREETCHED_MANIFEST and TCHED_ROUTER_CONFIG_DIR variables.
4|
5|use std::path::PathBuf;
6|
7|use anyhow::{Result, ensure};
8|
9|pub const DEFAULT_BINARY: &str = "/usr/local/libexec/op-dbus/threetched/threetched";
10|pub const DEFAULT_CONFIG_DIR: &str = "/var/lib/tched-router";
11|pub const DEFAULT_MANIFEST: &str = "/usr/share/op-dbus/threetched-manifests/tched-router.json";
12|
13|fn absolute_env_path(name: &str, default: &str) -> Result<PathBuf> {
14|    let path = std::env::var_os(name)
15|        .map(PathBuf::from)
16|        .unwrap_or_else(|| PathBuf::from(default));
17|    ensure!(path.is_absolute(), "{name} must be an absolute path");
18|    Ok(path)
19|}
20|
21|pub fn binary() -> Result<PathBuf> {
22|    absolute_env_path("THREETCHED_BIN", DEFAULT_BINARY)
23|}
24|
25|pub fn config_dir() -> Result<PathBuf> {
26|    absolute_env_path("TCHED_ROUTER_CONFIG_DIR", DEFAULT_CONFIG_DIR)
27|}
28|
29|pub fn manifest() -> Result<PathBuf> {
30|    absolute_env_path("THREETCHED_MANIFEST", DEFAULT_MANIFEST)
31|}
32|
33|/// Select the binary and provenance manifest used only to capture the sealed
34|/// CLI contract. Runtime dispatch continues to use [`binary`] and [`manifest`].
35|/// Build/seal invocations may point these selectors at a not-yet-installed
36|/// candidate, but must supply the pair together so provenance cannot drift.
37|pub(crate) fn capture_paths() -> Result<(PathBuf, PathBuf)> {
38|    match (
39|        std::env::var_os("THREETCHED_CAPTURE_BIN"),
40|        std::env::var_os("THREETCHED_CAPTURE_MANIFEST"),
41|    ) {
42|        (None, None) => Ok((binary()?, manifest()?)),
43|        (Some(binary), Some(manifest)) => {
44|            let binary = PathBuf::from(binary);
45|            let manifest = PathBuf::from(manifest);
46|            ensure!(binary.is_absolute(), "THREETCHED_CAPTURE_BIN must be an absolute path");
47|            ensure!(manifest.is_absolute(), "THREETCHED_CAPTURE_MANIFEST must be an absolute path");
48|            Ok((binary, manifest))
49|        }
50|        _ => anyhow::bail!("THREETCHED_CAPTURE_BIN and THREETCHED_CAPTURE_MANIFEST must be supplied together"),
51|    }
52|}","total_lines":52,"file_size":2176,"truncated":false,"is_binary":false,"is_image":false,"not_found":false}

